import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/docs-editor/overview-toolbar.png",i="/docs/images/docs-editor/overview-toolbar-mobile.png",f=JSON.parse('{"title":"Docs","description":"Docs is a page-based word processor where you write, format, and lay out documents with your team.","frontmatter":{"title":"Docs","description":"Docs is a page-based word processor where you write, format, and lay out documents with your team.","type":"overview"},"headers":[],"relativePath":"docs-editor/index.md","filePath":"docs-editor/index.md"}'),n={name:"docs-editor/index.md"};function d(l,e,h,c,p,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h1><p>Docs is a page-based word processor where you write, format, and lay out documents with your team.</p><p>Use it to:</p><ul><li>Write reports, proposals, and specs that print and export as real pages</li><li>Take meeting notes together, with everyone typing in the same document</li><li>Review a draft with comments and restore an earlier version if needed</li></ul><p><img src="'+s+'" alt="Docs editor with the formatting toolbar, the ruler, and a page of a project proposal"></p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong> and select <strong>New document</strong>. A blank Letter-size page opens.</li><li>Click the title in the header to rename the document, then click the page and start typing. Use the toolbar to <a href="/docs/docs-editor/format-text.html">format text</a>.</li><li>Click <strong>Share</strong> in the top right to invite people. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><p>To start from a ready-made layout instead, click <strong>New</strong> and select <strong>New from template</strong>. See <a href="/docs/collaborate/templates.html">Templates</a>.</p><p>New to the editor? Follow <a href="/docs/docs-editor/write-a-proposal.html">Write a project proposal</a>, which takes about 10 minutes.</p><h2 id="write-and-format" tabindex="-1">Write and format <a class="header-anchor" href="#write-and-format" aria-label="Permalink to &quot;Write and format&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/format-text.html">Format text</a>: bold, fonts, colors, headings and styles, alignment, line spacing, and links</li><li><a href="/docs/docs-editor/lists-and-indents.html">Lists and indents</a>: bulleted and numbered lists, nesting, and indents on the ruler</li><li><a href="/docs/docs-editor/paste-from-other-apps.html">Paste from other apps</a>: what is kept when you paste from a web page, a spreadsheet, or another document</li></ul><h2 id="add-tables-and-images" tabindex="-1">Add tables and images <a class="header-anchor" href="#add-tables-and-images" aria-label="Permalink to &quot;Add tables and images&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/tables.html">Tables</a>: insert a table, add rows and columns, merge cells, and color cell backgrounds</li><li><a href="/docs/docs-editor/images.html">Images</a>: upload, paste, or link an image, then resize it</li></ul><h2 id="lay-out-pages" tabindex="-1">Lay out pages <a class="header-anchor" href="#lay-out-pages" aria-label="Permalink to &quot;Lay out pages&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/page-layout.html">Page layout</a>: paper size, orientation, margins, page breaks, horizontal lines, headers, footers, and page numbers</li></ul><h2 id="review-and-finish" tabindex="-1">Review and finish <a class="header-anchor" href="#review-and-finish" aria-label="Permalink to &quot;Review and finish&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/find-and-spelling.html">Find and spelling</a>: find and replace text and fix misspelled words</li><li><a href="/docs/collaborate/comments.html">Comments</a>: select text and press <code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code> to start a thread</li><li><a href="/docs/collaborate/version-history.html">Version history</a>: see and restore earlier versions</li><li><a href="/docs/files/import-export.html">Import and export</a>: open a Word file, or download as Word (.docx), PDF (.pdf), Markdown (.md), or Plain text (.txt) from the <strong>Export</strong> (download icon) menu in the header</li></ul><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>You can write and format on a phone. The toolbar keeps undo, redo, <strong>Format painter</strong>, bold, italic, underline, colors, and <strong>Clear formatting</strong>; on a narrow screen, swipe the toolbar sideways to reach the colors and <strong>Clear formatting</strong>. Everything else is in the ⋮ menu at the right end of the toolbar (<strong>More formatting options</strong>), which stays in view. Comments, version history, and export move to the header&#39;s <strong>More</strong> menu. The ruler is hidden, and find, replace, and keyboard shortcuts need a hardware keyboard. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><p><img src="'+i+'" alt="Docs editor on a phone with the short toolbar and the More formatting options menu open"></p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard shortcuts</a></li><li><a href="/docs/files/import-export.html">Import and export</a></li><li><a href="/docs/start/troubleshooting.html">Troubleshooting</a></li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/write-a-proposal.html">Write a project proposal</a> to learn the editor end to end.</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a> to see who else is in the document.</li><li><a href="/docs/docs-editor/format-text.html">Format text</a> to set up headings you can reuse.</li></ul>',24)])])}const g=t(n,[["render",d]]);export{f as __pageData,g as default};
